package com.example.ai

import android.util.Log

/**
 * Provides the API key for MailCraft AI assistant features.
 * Safely resolves from BuildConfig, Secrets Gradle Plugin, or environment variables.
 */
object AiKeyProvider {
  private const val TAG = "AiKeyProvider"

  fun getApiKey(): String {
    // 1. Check direct BuildConfig.OPENROUTER_API_KEY generated by build.gradle.kts
    val directKey = try {
      val key = com.example.BuildConfig.OPENROUTER_API_KEY
      if (key.isNotBlank() && key != "YOUR_API_KEY") key else ""
    } catch (_: Throwable) {
      ""
    }
    if (directKey.isNotBlank()) return directKey.trim()

    // 2. Check Secrets Gradle Plugin reflection field (openrouter_api)
    val secretsKey = try {
      val field = com.example.BuildConfig::class.java.getField("openrouter_api")
      val v = field.get(null) as? String ?: ""
      if (v.isNotBlank() && v != "YOUR_API_KEY") v else ""
    } catch (_: Throwable) {
      ""
    }
    if (secretsKey.isNotBlank()) return secretsKey.trim()

    // 3. Check environment variables
    val envKey = System.getenv("openrouter_api") ?: System.getenv("OPENROUTER_API") ?: ""
    if (envKey.isNotBlank() && envKey != "YOUR_API_KEY") return envKey.trim()

    Log.w(TAG, "No valid AI API key detected in BuildConfig or environment.")
    return ""
  }

  fun hasValidKey(): Boolean = getApiKey().isNotBlank()
}
